 * mini-md — a tiny, hand-rolled Markdown subset renderer for comment boxes.
 *
 * Supported constructs:
 *   - paragraphs (blank-line separated)
 *   - **bold**
 *   - *italic*
 *   - `inline code`
 *   - fenced code blocks (``` ... ```)
 *   - links [text](url) — href allowlisted
 *   - unordered lists (- item)
 *
 * Security model:
 *   1. Every piece of source text is HTML-escaped BEFORE any markup is
 *      inserted. Raw HTML in user input can therefore never reach the output.
 *   2. Link URLs must pass an allowlist (http:, https:, mailto:, or relative).
 *      javascript:/data:/vbscript: etc. cause the link to degrade to plain
 *      text.
 *   3. Every emitted <a> gets rel="noopener noreferrer" target="_blank".
 */

const ESCAPE_MAP = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

/** Escape all HTML-significant characters in a raw string. */
export function escapeHtml(text) {
  return String(text).replace(/[&<>"']/g, (ch) => ESCAPE_MAP[ch]);
}

/**
 * Allowlist of safe URL schemes. A URL is safe if:
 *   - it starts with http:// or https://
 *   - it starts with mailto:
 *   - it is relative (no scheme at all)
 */
export function isSafeUrl(url) {
  const trimmed = url.trim();
  if (/^https?:\/\//i.test(trimmed)) return true;
  if (/^mailto:/i.test(trimmed)) return true;
  // Relative: must not contain a scheme like "foo:" before any "/", "?" or "#".
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(trimmed)) return false;
  return true;
}

const LINK_ATTRS = 'rel="noopener noreferrer" target="_blank"';

/**
 * Render inline markdown (bold, italic, code, links) on a single line.
 * Input is RAW text; everything is escaped as tokens are consumed.
 */
function renderInline(raw) {
  let out = '';
  let i = 0;
  let plain = ''; // buffer of escaped plain text

  const flush = () => {
    if (plain) {
      out += escapeHtml(plain);
      plain = '';
    }
  };

  while (i < raw.length) {
    // Inline code: `...`
    if (raw[i] === '`') {
      const end = raw.indexOf('`', i + 1);
      if (end !== -1) {
        flush();
        out += `<code>${escapeHtml(raw.slice(i + 1, end))}</code>`;
        i = end + 1;
        continue;
      }
    }

    // Links: [text](url)
    if (raw[i] === '[') {
      const match = /^\[([^\]\n]*)\]\(([^)\s]*)\)/.exec(raw.slice(i));
      if (match) {
        flush();
        const [, text, url] = match;
        if (isSafeUrl(url)) {
          out += `<a href="${escapeHtml(url)}" ${LINK_ATTRS}>${escapeHtml(text)}</a>`;
        } else {
          // Unsafe scheme: render as plain text "text (url)".
          out += `${escapeHtml(text)} (${escapeHtml(url)})`;
        }
        i += match[0].length;
        continue;
      }
    }

    // Bold: **...** (checked before single asterisk)
    if (raw[i] === '*' && raw[i + 1] === '*') {
      const end = raw.indexOf('**', i + 2);
      if (end !== -1) {
        flush();
        out += `<strong>${renderInline(raw.slice(i + 2, end))}</strong>`;
        i = end + 2;
        continue;
      }
    }

    // Italic: *...*
    if (raw[i] === '*') {
      const end = raw.indexOf('*', i + 1);
      if (end !== -1) {
        flush();
        out += `<em>${renderInline(raw.slice(i + 1, end))}</em>`;
        i = end + 1;
        continue;
      }
    }

    plain += raw[i];
    i++;
  }
  flush();
  return out;
}

/**
 * Render a markdown string to an HTML fragment.
 * Block-level parsing happens on RAW text; escaping happens inside the
 * inline renderer and for code blocks.
 */
export function renderMarkdown(source) {
  const lines = String(source).split(/\r?\n/);
  const blocks = [];
  let para = [];
  let listItems = null;

  const closePara = () => {
    if (para.length) {
      blocks.push(`<p>${renderInline(para.join('\n'))}</p>`);
      para = [];
    }
  };
  const closeList = () => {
    if (listItems) {
      blocks.push(`<ul>${listItems.map((li) => `<li>${renderInline(li)}</li>`).join('')}</ul>`);
      listItems = null;
    }
  };

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block ```
    const fenceMatch = /^```(.*)$/.exec(line);
    if (fenceMatch) {
      closePara();
      closeList();
      const lang = fenceMatch[1].trim();
      const codeLines = [];
      i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i])) {
        codeLines.push(lines[i]);
        i++;
      }
      i++; // skip closing fence (or run off end — treat as closed)
      const cls = /^[a-zA-Z0-9_-]+$/.test(lang) ? ` class="language-${lang}"` : '';
      blocks.push(`<pre><code${cls}>${escapeHtml(codeLines.join('\n'))}</code></pre>`);
      continue;
    }

    // Blank line ends paragraph/list
    if (line.trim() === '') {
      closePara();
      closeList();
      i++;
      continue;
    }

    // Unordered list item: "- text" (also "* text" / "+ text")
    const liMatch = /^\s*[-*+]\s+(.*)$/.exec(line);
    if (liMatch && !(liMatch[1].startsWith('*') || liMatch[1].startsWith('-'))) {
      closePara();
      if (!listItems) listItems = [];
      listItems.push(liMatch[1]);
      i++;
      continue;
    }

    // Paragraph line
    closeList();
    para.push(line);
    i++;
  }

  closePara();
  closeList();

  return blocks.join('\n');
}
