import { parse } from 'node-html-parser';
import { renderMarkdown, isSafeUrl, escapeHtml } from '../src/render.js';

/** Parse rendered HTML and collect all nodes + attribute names. */
function analyze(html) {
  const root = parse(html);
  const tags = [];
  const attrs = [];
  for (const node of root.querySelectorAll('*')) {
    tags.push(node.rawTagName.toLowerCase());
    for (const name of Object.keys(node.attributes)) attrs.push(name.toLowerCase());
  }
  return { root, tags, attrs };
}

describe('escapeHtml', () => {
