// ---------------------------------------------------------------------------
// Real XSS vector suite — the parsed tree must never contain dangerous nodes
// or on-* event handler attributes.
// ---------------------------------------------------------------------------

const PAYLOADS = [
  // The required vectors
  '[click](javascript:alert(1))',
  '<img src=x onerror=alert(1)>',
  '```\n<script>alert(1)</script>\n```',
  // Additional real-world vectors
  '[click](JAVASCRIPT:alert(1))',
  '[click]( javascript:alert(1) )',
  '[x](data:text/html,<script>alert(1)</script>)',
  '<script>alert(1)</script>',
  '<SCRIPT SRC=http://evil.com/x.js></SCRIPT>',
  '"><script>alert(1)</script>',
  "<img src='x' onerror='alert(1)'>",
  '<svg onload=alert(1)>',
  '<body onload=alert(1)>',
  '<iframe src="javascript:alert(1)">',
  '<a href="javascript:alert(1)">click</a>',
  '<div onmouseover=alert(1)>hover</div>',
  '<input onfocus=alert(1) autofocus>',
  '<video><source onerror=alert(1)>',
  '<math href="javascript:alert(1)">CLICKME</math>',
  '`<img src=x onerror=alert(1)>`',
  '**<img src=x onerror=alert(1)>**',
  '*[x](javascript:alert(1))*',
  '- <img src=x onerror=alert(1)>',
  '[![x](javascript:alert(1))](javascript:alert(2))',
];

describe('XSS payload suite', () => {
  for (const payload of PAYLOADS) {
    it(`neutralizes: ${JSON.stringify(payload)}`, () => {
      const html = renderMarkdown(payload);
      const { root, tags, attrs } = analyze(html);

      // No scriptable/embedded elements anywhere in the tree
      for (const banned of ['script', 'img', 'svg', 'iframe', 'object', 'embed', 'math', 'video', 'audio']) {
        expect(tags, `tag <${banned}> leaked for payload ${payload}`).not.toContain(banned);
      }

      // No event-handler attributes of any kind
      for (const attr of attrs) {
        expect(attr.startsWith('on'), `attribute ${attr} leaked for payload ${payload}`).toBe(false);
      }

      // No javascript:/data: hrefs survive even if an <a> exists
      for (const a of root.querySelectorAll('a')) {
        const href = (a.getAttribute('href') ?? '').toLowerCase();
        expect(href.startsWith('javascript:')).toBe(false);
        expect(href.startsWith('data:')).toBe(false);
        if (tags.includes('a')) {
          expect(a.getAttribute('rel')).toBe('noopener noreferrer');
          expect(a.getAttribute('target')).toBe('_blank');
        }
      }
    });
  }

  it('raw img payload appears only as escaped text', () => {
    const html = renderMarkdown('<img src=x onerror=alert(1)>');
    expect(html).toContain('&lt;img src=x onerror=alert(1)&gt;');
    const { tags } = analyze(html);
    expect(tags).not.toContain('img');
  });

  it('fenced block with script renders as escaped text inside pre code', () => {
    const html = renderMarkdown('```\n<script>alert(1)</script>\n```');
    const { root, tags } = analyze(html);
    expect(tags.filter((t) => t === 'pre').length).toBe(1);
    expect(tags.filter((t) => t === 'code').length).toBe(1);
    expect(root.querySelector('pre code').text).toBe('<script>alert(1)</script>');
    expect(tags).not.toContain('script');
  });
});
"})
